package za.ac.cput.domain;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity public class Customer extends User { private String driverLicenseNumber; private LocalDate dateOfBirth; @OneToOne(cascade=CascadeType.ALL) @JoinColumn(name="address_id") private HomeAddress address; @Embedded private NextOfKin nextOfKin; protected Customer(){}
 private Customer(Builder b){super(b);driverLicenseNumber=b.driverLicenseNumber;dateOfBirth=b.dateOfBirth;address=b.address;nextOfKin=b.nextOfKin;} public String getCustomerId(){return getUserId();} public String getDriverLicenseNumber(){return driverLicenseNumber;} public LocalDate getDateOfBirth(){return dateOfBirth;} public HomeAddress getAddress(){return address;} public NextOfKin getNextOfKin(){return nextOfKin;}
 public static class Builder extends User.Builder<Builder>{private String driverLicenseNumber;private LocalDate dateOfBirth;private HomeAddress address;private NextOfKin nextOfKin; public Builder setCustomerId(String v){return setUserId(v);} public Builder setDriverLicenseNumber(String v){driverLicenseNumber=v;return this;} public Builder setDateOfBirth(LocalDate v){dateOfBirth=v;return this;} public Builder setAddress(HomeAddress v){address=v;return this;} public Builder setNextOfKin(NextOfKin v){nextOfKin=v;return this;} public Builder copy(Customer c){setUserId(c.getUserId());setFirstName(c.getFirstName());setLastName(c.getLastName());setEmail(c.getEmail());setPhoneNumber(c.getPhoneNumber());setRole(c.getRole());driverLicenseNumber=c.driverLicenseNumber;dateOfBirth=c.dateOfBirth;address=c.address;nextOfKin=c.nextOfKin;return this;} @Override public Customer build(){return new Customer(this);} }
}